const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const year = 2021;
    // The Antarctic ozone hole season is typically August-November.
    const startDate = `${year}-08-01`;
    const endDate = `${year}-11-30`;
    // A large area of interest covering the Antarctic region.
    const antarctica = ee.Geometry.Point([0, -90]).buffer(5500000); // 5500 km radius

    // 2. Data Acquisition
    const s5p_collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_O3')
        .filterBounds(antarctica)
        .filterDate(startDate, endDate)
        .select(['O3_column_number_density', 'qa_value']);

    // Check if the collection is empty.
    const collectionSize = s5p_collection.size().getInfo();
    if (collectionSize === 0) {
        console.log(`No Sentinel-5P L3_O3 images found for the period ${startDate} to ${endDate}.`);
        console.log("A"); // C1
        return;
    }
    console.log(`Initial image collection size for ${year}: ${collectionSize}`);

    // 3. Processing
    // Function to calculate the area of the ozone hole for a single image.
    const calculateHoleArea = function(image) {
        // Apply a quality assurance mask. A common threshold for S5P is qa_value > 0.5.
        const qualityMask = image.select('qa_value').gt(0.5);

        // The ozone hole is defined as the area where the total ozone column is less than 220 Dobson Units (DU).
        // The band 'O3_column_number_density' is in mol/m^2.
        // Conversion: 1 mol/m^2 ≈ 2240 DU. So, 220 DU ≈ 0.0982 mol/m^2.
        const dobsonUnitThreshold = 0.0982;

        const ozoneHole = image.select('O3_column_number_density')
                               .updateMask(qualityMask)
                               .lt(dobsonUnitThreshold);

        // Calculate the area of the pixels that meet the ozone hole criteria.
        // ee.Image.pixelArea() gives area in square meters.
        const holeArea = ozoneHole.multiply(ee.Image.pixelArea())
                                  .reduceRegion({
                                      reducer: ee.Reducer.sum(),
                                      geometry: antarctica,
                                      scale: 5000, // Use a coarse scale to avoid timeout.
                                      maxPixels: 1e9
                                  }).get('O3_column_number_density');

        // Return the image with a new property for the calculated area in square kilometers.
        // Convert from m^2 to km^2 by dividing by 1e6.
        return image.set('hole_area_km2', ee.Number(holeArea).divide(1e6));
    };

    const areaCollection = s5p_collection.map(calculateHoleArea);

    // 4. Calculation
    // Find the maximum area recorded during the period.
    // The aggregate_max function finds the maximum value of a specified property in the collection.
    const maxArea = areaCollection.aggregate_max('hole_area_km2').getInfo();

    if (maxArea === null || typeof maxArea === 'undefined') {
        console.log("Calculation failed: Could not determine maximum ozone hole area.");
        console.log("C3");
        return;
    }

    // The reducer might return 0 if no pixels ever met the criteria (no hole formed or bad data).
    // Let's check for a very small number to confirm it's not a complete failure.
    if (maxArea < 1000) { 
        console.log(`No significant ozone hole area detected (Max Area: ${maxArea.toFixed(2)} km^2).`);
        console.log(`This could indicate no valid pixels after masking or a very small hole.`);
        const validPixelsCheck = s5p_collection.first().select('qa_value').gt(0.5).reduceRegion({
            reducer: ee.Reducer.count(), geometry: antarctica, scale: 5000, maxPixels: 1e9
        }).get('qa_value').getInfo();

        if(validPixelsCheck === 0) {
            console.log("No valid pixels found in the first image after QA masking.");
            console.log("C2");
        } else {
             // A valid zero or very small area was calculated.
            console.log("B");
        }
        return;
    }

    // 5. Validation & Final Answer
    const targetArea = 18e6; // 18 million square kilometers
    const maxAreaMillions = maxArea / 1e6;

    console.log(`Analysis Period: ${startDate} to ${endDate}`);
    console.log(`Maximum ozone hole area detected: ${maxAreaMillions.toFixed(2)} million km^2`);
    console.log(`Target size for comparison: ${targetArea / 1e6} million km^2`);

    if (maxArea >= targetArea) {
        console.log("Evidence: The maximum detected area exceeded the 18 million km^2 threshold.");
        console.log("A");
    } else {
        console.log("Evidence: The maximum detected area did not reach the 18 million km^2 threshold.");
        console.log("B");
    }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log("D");
  }
}

initEE();
